// Server-only exercise registry (plan §3.5, §7.1, §7.2) — CODE, not data.
//
// Compiled with the Worker; never imported by client code, never serialized
// into a response before the reveal gate. For every exercise: the compiled
// expected spec (result-based comparison — learner SQL is never inspected),
// the reference solution SQL and the maintainer-facing explanation. The
// matching client-safe definitions live in src/data/sqlExercises.ts; ids are
// shared and content tests keep the two aligned.
//
// Expected specs were generated by executing each shipped solution against
// the canonical snapshot (+ exercise setupSql) and inlining the result.
// tests/lib/sql-exercises.test.ts re-runs every solution and asserts 36/36
// pass — any drift between seed, solution and spec fails loudly.

import type { SqlExpectedSpec } from './sqlEvaluate'

export interface SqlExerciseDefinition {
  id: string
  difficulty: 'beginner' | 'intermediate' | 'advanced'
  /** Compiled expected specification for result-based comparison. */
  expected: SqlExpectedSpec
  /** Reference solution SQL (server-only). */
  solution: string
  /** Maintainer-facing explanation shipped with the gated reveal. */
  explanation: string
}

