export type SqlExerciseRegistry = readonly SqlExerciseDefinition[]

/** Learner-safe-adjacent lookup (never returns content before the reveal gate). */
export function findSqlExercise(id: string): SqlExerciseDefinition | null {
  return SQL_EXERCISES.find((exercise) => exercise.id === id) ?? null
}

/** Fail-closed lookup for paths that must have the definition. */
export function requireSqlExercise(id: string): SqlExerciseDefinition {
  const exercise = findSqlExercise(id)
  if (!exercise) {
    throw new Error('SQL exercise registry is missing an exercise.')
  }
  return exercise
}
